<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {api} from '../api';import {useSession,useCart} from '../stores';const props=defineProps<{mode:'login'|'register'}>();const router=useRouter(),session=useSession(),cart=useCart(),name=ref(''),email=ref(''),password=ref(''),error=ref(''),loading=ref(false);async function submit(){loading.value=true;error.value='';try{const body=props.mode==='register'?{name:name.value,email:email.value,password:password.value}:{email:email.value,password:password.value};session.user=await api(`/auth/${props.mode==='register'?'register':'login'}`,{method:'POST',body:JSON.stringify(body)});await cart.load();router.push('/')}catch(e:any){error.value=e.message}finally{loading.value=false}}</script>
<template><main class="auth-page"><form class="auth-card" @submit.prevent="submit"><RouterLink to="/" class="brand">SHOPORA</RouterLink><small>{{mode==='login'?'WELCOME BACK':'CREATE AN ACCOUNT'}}</small><h1>{{mode==='login'?'Sign in to your account':'Join the considered life.'}}</h1><p v-if="error" class="notice">{{error}}</p><label v-if="mode==='register'">Full name<input v-model="name" required minlength="2"/></label><label>Email<input v-model="email" type="email" required/></label><label>Password<input v-model="password" type="password" required minlength="8"/></label><button class="button" :disabled="loading">{{loading?'Please wait…':mode==='login'?'Sign in':'Create account'}}</button><p>{{mode==='login'?'New to Shopora?':'Already have an account?'}} <RouterLink :to="mode==='login'?'/register':'/login'">{{mode==='login'?'Create account':'Sign in'}}</RouterLink></p></form></main></template>
